DO $$ DECLARE d text; BEGIN SELECT pg_get_constraintdef(oid) INTO STRICT d FROM pg_constraint WHERE conrelid='cmd_command'::regclass AND conname='cmd_command_command_type_check'; ALTER TABLE cmd_command DROP CONSTRAINT cmd_command_command_type_check; EXECUTE format('ALTER TABLE cmd_command ADD CONSTRAINT cmd_command_command_type_check %s',replace(d,'CHECK (','CHECK (command_type=''start_spacecraft_journey_leg'' OR command_type=''complete_spacecraft_journey_leg'' OR ')); END $$;
CREATE TABLE journey_leg_execution(journey_leg_id bigint PRIMARY KEY,campaign_id bigint NOT NULL,ship_id bigint NOT NULL,execution_status text NOT NULL CHECK(execution_status IN('underway','completed')),duration_seconds bigint NOT NULL CHECK(duration_seconds>0),departure_day bigint NOT NULL,departure_second integer NOT NULL CHECK(departure_second BETWEEN 0 AND 86399),arrival_day bigint,arrival_second integer CHECK(arrival_second BETWEEN 0 AND 86399),start_command_id bigint NOT NULL UNIQUE REFERENCES cmd_command(command_id),complete_command_id bigint UNIQUE REFERENCES cmd_command(command_id),FOREIGN KEY(journey_leg_id,campaign_id) REFERENCES journey_leg(journey_leg_id,campaign_id),FOREIGN KEY(ship_id,campaign_id) REFERENCES ship_ship(ship_id,campaign_id),CHECK((execution_status='underway' AND arrival_day IS NULL AND arrival_second IS NULL AND complete_command_id IS NULL) OR (execution_status='completed' AND arrival_day IS NOT NULL AND arrival_second IS NOT NULL AND complete_command_id IS NOT NULL)));
CREATE TABLE cmd_spacecraft_leg_start_receipt(command_id bigint PRIMARY KEY REFERENCES cmd_command(command_id),journey_leg_id bigint NOT NULL UNIQUE REFERENCES journey_leg_execution(journey_leg_id),campaign_id bigint NOT NULL,ship_id bigint NOT NULL,duration_seconds bigint NOT NULL CHECK(duration_seconds>0),resource_plan_count smallint NOT NULL CHECK(resource_plan_count>=0),departure_day bigint NOT NULL,departure_second integer NOT NULL CHECK(departure_second BETWEEN 0 AND 86399),FOREIGN KEY(journey_leg_id,campaign_id) REFERENCES journey_leg(journey_leg_id,campaign_id),FOREIGN KEY(ship_id,campaign_id) REFERENCES ship_ship(ship_id,campaign_id));
CREATE TABLE cmd_spacecraft_leg_complete_receipt(command_id bigint PRIMARY KEY REFERENCES cmd_command(command_id),journey_leg_id bigint NOT NULL UNIQUE REFERENCES journey_leg_execution(journey_leg_id),campaign_id bigint NOT NULL,ship_id bigint NOT NULL,clock_day_before bigint NOT NULL,clock_second_before integer NOT NULL CHECK(clock_second_before BETWEEN 0 AND 86399),clock_day_after bigint NOT NULL,clock_second_after integer NOT NULL CHECK(clock_second_after BETWEEN 0 AND 86399),journey_completed boolean NOT NULL,FOREIGN KEY(journey_leg_id,campaign_id) REFERENCES journey_leg(journey_leg_id,campaign_id),FOREIGN KEY(ship_id,campaign_id) REFERENCES ship_ship(ship_id,campaign_id),CHECK((clock_day_after,clock_second_after)>(clock_day_before,clock_second_before)));
CREATE FUNCTION cmd_reject_spacecraft_journey_execution_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Spacecraft journey execution receipts are immutable'; END $$;
CREATE TRIGGER cmd_spacecraft_leg_start_immutable BEFORE UPDATE OR DELETE ON cmd_spacecraft_leg_start_receipt FOR EACH ROW EXECUTE FUNCTION cmd_reject_spacecraft_journey_execution_mutation();
CREATE TRIGGER cmd_spacecraft_leg_complete_immutable BEFORE UPDATE OR DELETE ON cmd_spacecraft_leg_complete_receipt FOR EACH ROW EXECUTE FUNCTION cmd_reject_spacecraft_journey_execution_mutation();
